false,"instructions":"Banco a 30°. Acima disso o exercício vira mais ombro do que peito.","muscles":["peito-superior","ombro-frontal"]},{"slug":"supino-inclinado-na-maquina","name":"Supino inclinado na máquina","measure":"weight_reps","category":"strength","equipment":"máquina","unilateral":false,"instructions":null,"muscles":["peito-superior","ombro-frontal"]},{"slug":"remada-baixa-no-cabo-triangulo","name":"Remada baixa no cabo (triângulo)","measure":"weight_reps","category":"strength","equipment":"polia","unilateral":false,"instructions":"Deixe os braços irem à frente para alongar as costas e puxe até a barriga.","muscles":["dorsal-espessura"]},{"slug":"remada-unilateral-com-halter","name":"Remada unilateral com halter","measure":"weight_reps","category":"strength","equipment":"halteres","unilateral":true,"instructions":null,"muscles":["dorsal-espessura"]},{"slug":"peck-deck","name":"Peck deck","measure":"weight_reps","category":"strength","equipment":"máquina","unilateral":false,"instructions":"Segure 1 s com as mãos juntas e volte devagar até alongar.","muscles":["peito-medial"]},{"slug":"crucifixo-com-halteres","name":"Crucifixo com halteres","measure":"weight_reps","category":"strength","equipment":"halteres","unilateral":false,"instructions":null,"muscles":["peito-medial"]},{"slug":"puxada-com-triangulo","name":"Puxada com triângulo","measure":"weight_reps","category":"strength","equipment":"máquina","unilateral":false,"instructions":"Pegada neutra. Puxe até o alto do peito com o tronco levemente para trás.","muscles":["dorsal-largura"]},{"slug":"barra-fixa","name":"Barra fixa","measure":"weight_reps","category":"strength","equipment":"peso corporal","unilateral":false,"instructions":null,"muscles":["dorsal-largura"]},{"slug":"desenvolvimento-com-halteres-sentado","name":"Desenvolvimento com halteres sentado","measure":"weight_reps","category":"strength","equipment":"halteres","unilateral":false,"instructions":"Desça os halteres até a altura das orelhas, sem