{"slug":"rosca-martelo-na-corda","name":"Rosca martelo na corda","measure":"weight_reps","category":"strength","equipment":"polia","unilateral":false,"instructions":null,"muscles":["braquial"]},{"slug":"remada-alta-com-pegada-aberta","name":"Remada alta com pegada aberta","measure":"weight_reps","category":"strength","equipment":"máquina","unilateral":false,"instructions":"Pegada na largura dos ombros ou mais aberta. Suba só até a altura do peito para poupar o ombro.","muscles":["ombro-medial","trapezio-superior"]},{"slug":"remada-alta-na-polia","name":"Remada alta na polia","measure":"weight_reps","category":"strength","equipment":"polia","unilateral":false,"instructions":null,"muscles":["ombro-medial","trapezio-superior"]},{"slug":"triceps-na-polia-com-barra-reta","name":"Tríceps na polia com barra reta","measure":"weight_reps","category":"strength","equipment":"polia","unilateral":false,"instructions":"Cotovelos colados no corpo. Estenda até o fim.","muscles":["triceps"]},{"slug":"triceps-testa","name":"Tríceps testa","measure":"weight_reps","category":"strength","equipment":"máquina","unilateral":false,"instructions":null,"muscles":["triceps"]},{"slug":"face-pull","name":"Face pull","measure":"weight_reps","category":"strength","equipment":"polia","unilateral":false,"instructions":"Corda na altura do rosto. Puxe em direção aos olhos abrindo as mãos. Ótimo para a postura de quem passa o dia sentado.","muscles":["ombro-posterior","trapezio-medio"]},{"slug":"triceps-com-pegada-inversa","name":"Tríceps com pegada inversa","measure":"weight_reps","category":"strength","equipment":"máquina","unilateral":false,"instructions":"Palmas para cima. Carga menor do que na barra reta.","muscles":["triceps"]},{"slug":"triceps-unilateral-na-polia","name":"Tríceps unilateral na polia","measure":"weight_reps","category":"strength","equipment":"polia","unilateral":true,"instructions":null,"muscles":["triceps"]},{"slug":"flexao-de-punho-com-barra","name":"Flexão de punho com barra","measure":"weight_reps","category":"strength","equipment":"barra","unilateral":false,"instructions":"Antebraço apoiado. Deixe a barra rolar até a ponta dos dedos e feche a mão: isso engrossa a parte perto do punho.","muscles":["antebraco-flexores"]},{"slug":"flexao-de-punho-com-halteres","name":"Flexão de punho com halteres","measure":"weight_reps","category":"strength","equipment":"halteres","unilateral":false,"instructions":null,"muscles":["antebraco-flexores"]},{"slug":"extensao-de-punho","name":"Extensão de punho","measure":"weight_reps","category":"strength","equipment":"máquina","unilateral":false,"instructions":"Palma para baixo, movimento curto e controlado.","muscles":["antebraco-extensores"]},{"slug":"extensao-de-punho-com-halteres","name":"Extensão de punho com halteres","measure":"weight_reps","category":"strength","equipment":"halteres","unilateral":false,"instructions":null,"muscles":["antebraco-extensores"]},{"slug":"queixo-para-tras-deitado","name":"Queixo para trás deitado","measure":"reps","category":"isometric","equipment":"peso corporal","unilateral":false,"instructions":"Deitado de barriga para cima, sem travesseiro, joelhos dobrados. Faça um \"sim\" bem pequeno, levando o queixo para trás como se fizesse papada, sem tirar a cabeça do chão. Segure 10 s respirando normalmente e solte. Se os músculos da frente do pescoço endurecerem, faça o movimento menor.","muscles":["flexores-profundos-pescoco"]},{"slug":"queixo-para-tras-sentado-encostado-na-parede","name":"Queixo para trás sentado, encostado na parede","measure":"reps","category":"isometric","equipment":"peso corporal","unilateral":false,"instructions":null,"muscles":["flexores-profundos-pescoco"]},{"slug":"isometria-com-a-mao","name":"Isometria com a mão","measure":"time","category":"isometric","equipment":"peso corporal","unilateral":false,"instructions":"Sentado, costas retas, olhando para a frente. Mão na testa: empurre a cabeça contra a mão e segure com a mão, sem deixar a cabeça se mover. Depois com a mão atrás da cabeça e depois em cada lado, na altura da orelha. A cabeça não se mexe: só os músculos trabalham.","muscles":["pescoco-geral"]},{"slug":"isometria-com-uma-toalha","name":"Isometria com uma toalha","measure":"time","category":"isometric","equipment":"peso corporal","unilateral":false,"instructions":null,"muscles":["pescoco-geral"]},{"slug":"crucifixo-inverso-com-elastico","name":"Crucifixo inverso com elástico","measure":"reps","category":"strength","equipment":"elástico","unilateral":false,"instructions":"Em pé, segure o elástico na frente do peito com os braços retos. Abra os braços até o elástico encostar no peito, juntando as escápulas. Ombros longe das orelhas e queixo levemente para trás.","muscles":["ombro-posterior","trapezio-medio"]},{"slug":"crucifixo-inverso-com-garrafas-de-agua","name":"Crucifixo inverso com garrafas de água","measure":"reps","category":"strength","equipment":"carga caseira","unilateral":false,"instructions":null,"muscles":["ombro-posterior","trapezio-medio"]},{"slug":"remada-unilateral-com-mochila","name":"Remada unilateral com mochila","measure":"weight_reps","category":"strength","equipment":"carga caseira","unilateral":true,"instructions":"Mão e joelho apoiados na cama ou numa cadeira, costas retas. Puxe a mochila até o quadril levando o cotovelo para trás. Pescoço alinhado com as costas, olhando para o chão, sem esticar o queixo. Anote o peso da mochila no campo de carga.","muscles":["dorsal-espessura"]},{"slug":"remada-com-elastico-preso-na-porta","name":"Remada com elástico preso na porta","measure":"weight_reps","category":"strength","equipment":"elástico","unilateral":false,"instructions":null,"muscles":["dorsal-espessura"]},{"slug":"y-e-t-deitado-de-brucos","name":"Y e T deitado de bruços","measure":"reps","category":"strength","equipment":"peso corporal","unilateral":false,"instructions":"De bruços, testa apoiada numa toalha dobrada, polegares para cima. Levante os braços em Y (na diagonal, acima da cabeça) 8 vezes e depois em T (abertos para os lados) 8 vezes. Movimento pequeno e lento, sem tirar a testa da toalha.","muscles":["trapezio-medio"]},{"slug":"y-e-t-em-pe-com-o-tronco-inclinado","name":"Y e T em pé, com o tronco inclinado","measure":"reps","category":"strength","equipment":"peso corporal","unilateral":false,"instructions":null,"muscles":["trapezio-medio"]},{"slug":"alongamento-do-trapezio","name":"Alongamento do trapézio","measure":"time","category":"mobility","equipment":"peso corporal","unilateral":false,"instructions":"Sentado, segure o assento da cadeira com a mão direita. Incline a orelha esquerda em direção ao ombro esquerdo e, com a mão esquerda, puxe a cabeça de leve. Troque de lado.","muscles":["trapezio-superior"]},{"slug":"em-pe-com-a-mao-atras-das-costas","name":"Em pé, com a mão atrás das costas","measure":"time","category":"mobility","equipment":"máquina","unilateral":false,"instructions":null,"muscles":["trapezio-superior"]},{"slug":"alongamento-do-elevador-da-escapula","name":"Alongamento do elevador da escápula","measure":"time","category":"mobility","equipment":"peso corporal","unilateral":false,"instructions":"Sentado, gire a cabeça uns 45° para a esquerda e leve o nariz em direção à axila esquerda, puxando de leve com a mão esquerda. Você sente atrás do pescoço, do lado direito. Troque de lado.","muscles":["elevador-escapula"]},{"slug":"peitoral-na-porta","name":"Peitoral na porta","measure":"time","category":"mobility","equipment":"peso corporal","unilateral":false,"instructions":"Antebraços apoiados no batente da porta, cotovelos na altura dos ombros. Dê um passo à frente até sentir o peito abrir. Peito fechado puxa os ombros e a cabeça para a frente.","muscles":["peito-medial"]},{"slug":"peitoral-na-parede-um-braco-por-vez","name":"Peitoral na parede, um braço por vez","measure":"time","category":"mobility","equipment":"peso corporal","unilateral":false,"instructions":null,"muscles":["peito-medial"]}]}$seed$::jsonb;
  m jsonb; e jsonb; mg text; n int;
begin
  for m in select * from jsonb_array_elements(d->'muscles') loop
    insert into public.muscle_groups (slug, name, parent_id, position)
    values (m->>'slug', m->>'name', (select id from public.muscle_groups where slug = m->>'parent'), (m->>'position')::smallint);
  end loop;

  for e in select * from jsonb_array_elements(d->'exercises') loop
    insert into public.exercises (slug, name, measure, category, equipment, unilateral, instructions)
    values (e->>'slug', e->>'name', e->>'measure', e->>'category', e->>'equipment', (e->>'unilateral')::boolean, e->>'instructions');
    n := 0;
    for mg in select * from jsonb_array_elements_text(e->'muscles') loop
      insert into public.exercise_muscles (exercise_id, muscle_group_id, is_primary)
      select x.id, g.id, n = 0 from public.exercises x, public.muscle_groups g
       where x.slug = e->>'slug' and x.owner_id is null and g.slug = mg;
      n := n + 1;
    end loop;
  end loop;
end
$body$;
